(() => {
  const d = $json.output || $json;
  const skills = d.skills || {};
  const projects = d.projects || {};
  const improvement = d.resume_improvement || {};

  const bulletList = (arr) => {
    if (!Array.isArray(arr) || arr.length === 0) return "- None";
    return arr.map(x => "- " + (typeof x === "string" ? x : JSON.stringify(x))).join("\n");
  };

  return `
# 📄 RESUME ANALYSIS REPORT

## 🎯 Target Role
${d.target_role || "Not specified"}

## 📊 Overall Assessment

- Overall Match Score: ${d.overall_match_score ?? "N/A"}/100
- ATS Score: ${d.ats_score ?? "N/A"}/100
- Hiring Probability: ${d.hiring_probability ?? "N/A"}%
- Match Status: ${d.match_status || "N/A"}
- Job Description Provided: ${d.job_description_provided ?? "N/A"}

---

# 🛠️ SKILLS ANALYSIS

## ✅ Skills Present
${bulletList(skills.present)}

## ❌ Missing Skills
${bulletList(skills.missing)}

## 🚨 Critical Skills
${bulletList(skills.critical)}

---

# 🔍 JOB DESCRIPTION MATCH

${bulletList(d.job_description_match.matched_requirements || "No JD match information available", null, 2)}

---

# 💼 PROJECT ANALYSIS

## Total Projects
${projects.total ?? "N/A"}

## ✅ Relevant Projects
${bulletList(projects.relevant)}

## ⚠️ Partially Relevant Projects
${bulletList(projects.partially_relevant)}

---

# ⚠️ RESUME WEAKNESSES

${bulletList(d.resume_weaknesses)}

---

# 💡 RECOMMENDATIONS

${bulletList(d.recommendations)}

---

# ✨ RESUME IMPROVEMENT PLAN

## 🛠️ Skill Section

${bulletList(improvement.skills_section)}

## 💻 Project Section
${bulletList(improvement.projects_section)}


## 💼 Experience Section
${bulletList(improvement.experience_section || {}, null, 2)}

## 🎓 Education Section
${bulletList(improvement.education_section || {}, null, 2)}

## 📜 Certifications Section
${bulletList(improvement.certifications_section || {}, null, 2)}

## 📝 Summary Section
${bulletList(improvement.summary_section || {}, null, 2)}

## 🔑 ATS Keywords
${bulletList(improvement.ats_keywords || [], null, 2)}

## 🏗️ Overall Structure
${bulletList(improvement.overall_structure || {}, null, 2)}

---

# 🏁 FINAL DECISION
${d.final_decision || "Not specified"}

---

## ✅ ANALYSIS COMPLETE

Use the recommendations above to improve your resume for the target role.
`;
})()
}}

