for (const item of $input.all()) {
  let rawData = item.json.report || "";
  // Agar report ke andar JSON ya object string ki tarah hai toh use parse karne ki koshish karein,
  // warna agar yeh pehle se hi formatted text hai toh ise seedhe clean karke bhej dein.
  let formattedOutput = "";

  try {
    // Agar yeh JSON string hui toh parse hogi
    let parsedData = typeof rawData === 'string' ? JSON.parse(rawData) : rawData;

    // Agar object hai toh usko human readable headings mein convert karna
    formattedOutput += `### 📄 Resume Analysis Report\n\n`;
    for (const [key, value] of Object.entries(parsedData)) {
      let title = key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase());
      formattedOutput += `**${title}:**\n${typeof value === 'object' ? JSON.stringify(value, null, 2) : value}\n\n`;
    }
  } catch (e) {
    // Agar yeh normal text ya string hai toh ise direct format mein use karein
    formattedOutput = rawData;
  }

  // Naya field 'response' create karna jise chat mein bhej sakein
  item.json.response = formattedOutput.trim();
}

return $input.all();
